<script setup lang="ts">
import { organOrder } from '~/utils/puzzles.mjs'
const {state,change,undo,reset,canUndo,saveError}=usePuzzleState('organ')
const active=ref(0)
const order=computed(()=>organOrder(state.value.slots))
function pick(n:number) { const slots=state.value.slots.slice(); slots[active.value]=n; change({slots}); const next=slots.indexOf(null); if(next>=0) active.value=next }
</script>
<template><div class="puzzle"><p>Record all five positions from the organ screen. Put <strong>Static</strong> exactly where the distorted symbol appears.</p><div class="p-row"><button v-for="(n,i) in state.slots" :key="i" :aria-label="`Edit position ${i+1}`" :aria-pressed="active===i" @click="active=i">{{ i+1 }}: {{ n===null?'?':n===0?'Static':`Symbol ${n}` }}</button></div><div class="p-grid"><button v-for="n in 5" :key="n" class="p-card" :aria-label="`Symbol ${n}`" @click="pick(n)"><img :src="`/tools/astra-pillars/${n}.png`" :alt="`Symbol ${n}`"><span>Symbol {{ n }}</span></button><button @click="pick(0)">≈ Static</button></div><div class="p-result" aria-live="polite"><strong>Interact with the Mars pillars in this order</strong><ol v-if="order" class="p-sequence"><li v-for="(n,i) in order" :key="i"><small>{{ i+1 }}{{ state.slots[i]===0?' · inferred':'' }}</small><img :src="`/tools/astra-pillars/${n}.png`" :alt="`Symbol ${n}`" width="50" height="50"><span>Symbol {{ n }}</span></li></ol><p v-else>Select four different symbols and one Static slot.</p></div><details><summary>Symbol and pillar reference</summary><img src="/tools/astra-pillars/reference.webp" alt="Organ symbols and corresponding Mars pillar symbols" style="width:100%;height:auto"><p>First activate the five pillar antennas with the LGM-1. Then interact with their symbols in the displayed order.</p></details><PuzzleActions :can-undo="canUndo" :save-error="saveError" @undo="undo" @reset="reset" /></div></template>
